c.python:
class Solution:
    def countMonobit(self, n):
        ans = 0
        for x in range(n + 1):
            b = x & 1
            t, ok = x, True
            while t:
                if t & 1 != b:
                    ok = False
                    break
                t >>= 1
            ans += ok
        return ans

