class Solution {
public:
    int countMonobit(int n) {
        int ans = 0;
        for (int x = 0; x <= n; x++) {
            int b = x & 1; bool ok = true;
            for (int t = x; t; t >>= 1) if ((t & 1) != b) ok = false;
            ans += ok;
        }
        return ans;
    }
};

